    rendered = render(escaped, emoji=False)
    assert rendered.plain == text


@settings(max_examples=300, deadline=None)
@given(text=st.text())
def test_strip_control_codes_never_crashes(text):
    result = strip_control_codes(text)
    assert isinstance(result, str)


@settings(max_examples=300, deadline=None)
@given(text=st.text())
