@given(text=st.text())
def test_replace_never_crashes(text):
    result = Emoji.replace(text)
    assert isinstance(result, str)


@settings(max_examples=300, deadline=None)
@given(text=st.text())
def test_cell_len_never_crashes(text):
    result = cell_len(text)
