    assert result >= 0


@settings(max_examples=300, deadline=None)
@given(text=st.text())
def test_cached_cell_len_never_crashes(text):
    result = cached_cell_len(text)
    assert isinstance(result, int)
    assert result >= 0


@settings(max_examples=300, deadline=None)
@given(
    size=st.integers(min_value=-10**12, max_value=10**18),
    precision=st.one_of(st.none(), st.integers(min_value=0, max_value=10)),
    separator=st.sampled_from([" ", "", "-", "_"]),
)
def test_decimal_never_crashes(size, precision, separator):
    result = decimal(size, precision=precision, separator=separator)
    assert isinstance(result, str)


